mapper.update:
UPDATE t_user
SET token_version = token_version + 1,
    token_revoke_reason = #{reason},
    token_revoked_at = #{now},
    updated_at = #{now}
WHERE id = #{id}

UPDATE t_user
SET avatar_file_id = #{fileId},
    profile_version = profile_version + 1,
    updated_at = #{now}
WHERE id = #{id}

UPDATE t_user
SET avatar_file_id = NULL,
    updated_at = #{now}
WHERE id = #{id}
